const suffixVi=" Mỗi bài phải phân biệt chứng cứ, diễn giải và ký ức; ghi rõ người tạo nguồn, thời điểm, phạm vi, điều có thể suy ra và điều còn bất định. Học sinh đối chiếu văn kiện với nghiên cứu bảo tàng, đặt câu hỏi về quyền lực và tiếng nói bị thiếu, ghi locator để người khác kiểm tra lại. Các chủ đề chiến tranh, Đảng, đối ngoại và Hồ Chí Minh cần ngôn ngữ chính xác, tôn trọng con người, luật pháp quốc tế và không kích động thù ghét.";
const suffixEn=" Each lesson distinguishes evidence, interpretation, and memory; it states who made a source, when, its scope, what can be inferred, and what remains uncertain. Students compare records with museum research, ask whose voices are missing, and record locators for verification. Topics on war, the Party, foreign relations, and Ho Chi Minh require precise language, respect for people and international law, and no incitement to hatred.";
const reviewVi=" Reviewer nội bộ xác nhận quy trình biên tập, không thay thế Hội đồng sử học độc lập. Khi có nguồn mới hoặc bất đồng, bài phải ghi diff, mức chắc chắn và chuyển dual review trước khi xuất bản.";
const reviewEn=" The internal reviewer certifies editorial process and is not an independent historian council. New evidence or disagreement requires a diff, confidence statement, and dual review before publication.";

export const grade12Lessons:Grade12LessonSeed[]=[
 {id:"lesson-g12-world-cold-war",requirementId:"g12-world-during-after-cold-war",track:"MANDATORY",sourceIds:["source-g12-moet-programme","source-g12-un-cold-war"],vi:{title:"Thế giới trong và sau Chiến tranh lạnh",slug:"the-gioi-trong-va-sau-chien-tranh-lanh",summary:"Chiến tranh lạnh định hình trật tự, xung đột và hợp tác quốc tế; sau 1991 thế giới biến đổi nhưng không trở thành một cực đơn giản.",body:"Chiến tranh lạnh là một cấu trúc cạnh tranh toàn cầu sau Chiến tranh thế giới thứ hai, gắn với đối đầu Hoa Kỳ–Liên Xô, liên minh quân sự, chạy đua vũ trang, ý thức hệ, viện trợ và các cuộc chiến tranh ủy nhiệm. Tuy nhiên, các xã hội ở châu Á, châu Phi, Mỹ Latinh và châu Âu không chỉ là quân cờ; phong trào giải phóng dân tộc, lựa chọn phát triển và tranh đấu xã hội cũng tác động đến trật tự quốc tế. Liên Hợp Quốc tạo diễn đàn pháp lý và ngoại giao nhưng bị giới hạn bởi quyền phủ quyết, cạnh tranh cường quốc và việc thực thi không đồng đều. Sau 1991, toàn cầu hóa, công nghệ, các trung tâm kinh tế mới, xung đột khu vực, biến đổi khí hậu và dịch bệnh tạo một thế giới liên kết nhưng bất bình đẳng. Học sinh cần phân biệt “kết thúc một đối đầu lưỡng cực” với “kết thúc mọi xung đột”. Khi đọc bản đồ liên minh hoặc số liệu quốc phòng, phải ghi thời điểm, đơn vị và nguồn. Lịch sử thế giới sau Chiến tranh lạnh không phải lời tiên tri; nó giúp nhận diện cấu trúc, lựa chọn và bất định. Học bài này để hiểu hợp tác, luật pháp quốc tế và trách nhiệm công dân toàn cầu, không để xếp hạng hay kích động đối đầu."+suffixVi,learningObjectives:["Phân tích đặc điểm và tác động của Chiến tranh lạnh.","Giải thích biến đổi quốc tế sau 1991 bằng nhiều yếu tố.","Đánh giá vai trò và giới hạn của Liên Hợp Quốc và hợp tác quốc tế."],originalSummary:"Chiến tranh lạnh và thế giới sau 1991 là lịch sử của cạnh tranh, giải phóng, hợp tác và bất định liên tục.",analysis:"Mô hình hai cực hữu ích nhưng không đủ; bài học phải giữ chủ thể khu vực và các hệ quả xã hội bên dưới cấp độ cường quốc.",debates:[{title:"Sau 1991 thế giới có trở thành một cực ổn định không?",summary:"Trật tự thay đổi nhưng cạnh tranh, trung tâm quyền lực mới và xung đột khu vực tiếp tục; kết luận cần gắn thời điểm.",claimIds:["claim-g12-cold-war-structure","claim-g12-post1991-change"]}]},en:{title:"The world during and after the Cold War",slug:"the-world-during-and-after-the-cold-war",summary:"The Cold War shaped order, conflict, and cooperation; after 1991 the world changed without becoming a simple single pole.",body:"The Cold War was a global structure of competition after the Second World War, involving the United States and Soviet Union, military alliances, arms races, ideology, aid, and proxy wars. Societies in Asia, Africa, Latin America, and Europe were not merely pieces on a board: decolonisation, development choices, and social movements also shaped international order. The United Nations offered legal and diplomatic forums but faced veto power, great-power rivalry, and uneven enforcement. After 1991, globalisation, technology, new economic centres, regional conflict, climate change, and pandemics created a connected yet unequal world. Students distinguish the end of a bipolar confrontation from the end of all conflict. Alliance maps and defence statistics need dates, units, and sources. Post-Cold-War history is not a prophecy; it reveals structures, choices, and uncertainty. The lesson supports cooperation, international law, and global responsibility rather than rankings or confrontation."+suffixEn,learningObjectives:["Analyse features and effects of the Cold War.","Explain international change after 1991 through multiple factors.","Assess the UN and international cooperation with their limits."],originalSummary:"Cold War and post-1991 history involve continuing competition, liberation, cooperation, and uncertainty.",analysis:"A bipolar model helps but is incomplete; preserve regional agency and social consequences below great-power scale."+reviewEn,debates:[{title:"Did the world become a stable single pole after 1991?",summary:"Order changed while competition, new power centres, and regional conflicts continued; conclusions need dates.",claimIds:["claim-g12-cold-war-structure","claim-g12-post1991-change"]}]},claims:[{id:"claim-g12-cold-war-structure",claimType:"CONTEXT",assessment:"CONFIRMED",statementVi:"Chương trình lớp 12 yêu cầu phân tích trật tự thế giới và Chiến tranh lạnh trong và sau năm 1945.",statementEn:"The Grade 12 programme asks students to analyse world order and the Cold War during and after 1945.",sourceId:"source-g12-moet-programme",locator:"Mạch lớp 12 ‘Thế giới trong và sau Chiến tranh lạnh’",note:"Claim khóa phạm vi chương trình, không giản lược thành một cặp quốc gia."},{id:"claim-g12-post1991-change",claimType:"CONTEXT",assessment:"CONFIRMED",statementVi:"Lịch sử sau 1991 cần đọc cùng toàn cầu hóa, công nghệ, xung đột khu vực và các thách thức xuyên quốc gia.",statementEn:"Post-1991 history should be read with globalisation, technology, regional conflict, and transnational challenges.",sourceId:"source-g12-un-cold-war",locator:"UN history — post-war international institutions and changing order",note:"Claim là khung phân tích, không phải chỉ số định lượng."}]},
 {id:"lesson-g12-asean",requirementId:"g12-asean-history",track:"MANDATORY",sourceIds:["source-g12-moet-programme","source-g12-asean-history"],vi:{title:"ASEAN: những chặng đường lịch sử",slug:"asean-nhung-chang-duong-lich-su",summary:"ASEAN phát triển từ hợp tác khu vực năm 1967 qua mở rộng thành viên, đối thoại và các giới hạn của đồng thuận.",body:"ASEAN được thành lập năm 1967 qua Tuyên bố Bangkok trong bối cảnh Đông Nam Á chịu tác động của thuộc địa, chiến tranh lạnh và nhu cầu giảm xung đột. Tổ chức mở rộng thành viên theo những thời điểm khác nhau, tạo một diễn đàn để các quốc gia Đông Nam Á trao đổi về an ninh, kinh tế, văn hóa và phát triển. Nguyên tắc tôn trọng chủ quyền, không can thiệp và đồng thuận giúp các nước có không gian hợp tác, nhưng cũng khiến phản ứng chung trước khủng hoảng đôi khi chậm hoặc không đồng đều. Việt Nam gia nhập ASEAN năm 1995; việc tham gia cần được đọc trong bối cảnh Đổi mới, hội nhập và quan hệ khu vực. Học sinh nên phân biệt văn kiện thành lập, hoạt động của thể chế và trải nghiệm của người dân. Một tuyên bố chung cho biết mục tiêu chính thức, không tự chứng minh mọi kết quả. Khi nghiên cứu một chặng đường, lập dòng thời gian gồm thành viên, sáng kiến, khủng hoảng, thỏa thuận và tiếng nói xã hội. ASEAN không phải một nhà nước siêu quốc gia và cũng không phải câu chuyện thành công tuyến tính; đây là thử nghiệm hợp tác trong một khu vực đa dạng. Bài học khuyến khích hiểu láng giềng, tôn trọng khác biệt và giải quyết bất đồng bằng đối thoại."+suffixVi,learningObjectives:["Trình bày các mốc hình thành và phát triển của ASEAN.","Phân tích nguyên tắc hợp tác và giới hạn thể chế.","Liên hệ việc Việt Nam gia nhập ASEAN với Đổi mới và hội nhập."],originalSummary:"ASEAN là một tiến trình hợp tác khu vực nhiều thành tựu và giới hạn, không phải một nhà nước thống nhất.",analysis:"Đọc ASEAN từ văn kiện và thực tiễn xã hội giúp tránh cả ca ngợi trừu tượng lẫn phủ nhận giá trị hợp tác.",debates:[{title:"Đồng thuận có luôn tạo ra quyết định tốt nhất không?",summary:"Đồng thuận bảo vệ không gian chủ quyền nhưng có thể làm chậm hành động; đánh giá cần đặt trong từng khủng hoảng.",claimIds:["claim-g12-asean-founding","claim-g12-asean-vietnam"]}]},en:{title:"ASEAN: historical milestones",slug:"asean-historical-milestones",summary:"ASEAN grew from regional cooperation in 1967 through enlargement, dialogue, and the limits of consensus.",body:"ASEAN was established in 1967 through the Bangkok Declaration amid colonial legacies, the Cold War, and a need to reduce conflict in Southeast Asia. It expanded membership at different moments and created forums for security, economic, cultural, and development exchange. Respect for sovereignty, non-interference, and consensus create room for cooperation but can make common responses to crises slow or uneven. Vietnam joined ASEAN in 1995; this belongs in the context of Đổi mới, integration, and regional relations. Students distinguish founding documents, institutional activity, and people's experience. A joint statement shows official aims, not every outcome. Build a timeline of members, initiatives, crises, agreements, and social voices. ASEAN is neither a supranational state nor a linear success story; it is a cooperation experiment in a diverse region. The lesson supports understanding neighbours, respecting difference, and dialogue."+suffixEn,learningObjectives:["Outline ASEAN's formation and development.","Analyse cooperation principles and institutional limits.","Relate Vietnam's membership to Đổi mới and integration."],originalSummary:"ASEAN is a regional cooperation process with achievements and limits, not a unified state.",analysis:"Reading ASEAN through documents and social practice avoids abstract praise and dismissal of cooperation."+reviewEn,debates:[{title:"Does consensus always produce the best decision?",summary:"Consensus protects sovereignty space but may slow action; assess each crisis in context.",claimIds:["claim-g12-asean-founding","claim-g12-asean-vietnam"]}]},claims:[{id:"claim-g12-asean-founding",claimType:"DATE",assessment:"CONFIRMED",statementVi:"ASEAN được thành lập tại Bangkok ngày 8 tháng 8 năm 1967 qua Tuyên bố Bangkok.",statementEn:"ASEAN was established in Bangkok on 8 August 1967 through the Bangkok Declaration.",sourceId:"source-g12-asean-history",locator:"ASEAN — The Founding of ASEAN, Bangkok Declaration",note:"Claim dùng nguồn tổ chức chính thức và giữ mốc thành lập."},{id:"claim-g12-asean-vietnam",claimType:"DATE",assessment:"CONFIRMED",statementVi:"Việt Nam gia nhập ASEAN năm 1995, mở rộng không gian hợp tác khu vực của thời kỳ Đổi mới.",statementEn:"Vietnam joined ASEAN in 1995, widening the regional cooperation space during Đổi mới.",sourceId:"source-g12-moet-programme",locator:"Mạch ASEAN và hội nhập trong chương trình lớp 12",note:"Claim nêu mốc chương trình; cần đối chiếu văn kiện gia nhập khi xuất bản chuyên khảo."}]},
 {id:"lesson-g12-vietnam-1945-1975",requirementId:"g12-vietnam-1945-1975",track:"MANDATORY",sourceIds:["source-g12-moet-programme","source-g12-august-revolution","source-g12-party-chronology","source-g12-vietnam-dien-bien"],vi:{title:"Cách mạng, kháng chiến và bảo vệ Tổ quốc 1945–1975",slug:"cach-mang-khang-chien-va-bao-ve-to-quoc-1945-1975",summary:"Từ Cách mạng tháng Tám đến thống nhất đất nước là một chuỗi biến động chính trị, quân sự, ngoại giao và xã hội với tổn thất lớn.",body:"Cách mạng tháng Tám năm 1945 đưa tới sự ra đời của nước Việt Nam Dân chủ Cộng hòa trong bối cảnh Nhật đầu hàng, khủng hoảng thuộc địa và lực lượng cách mạng cùng quần chúng nổi dậy giành chính quyền. Sau đó, nhà nước mới phải đối mặt với nạn đói, thiếu thốn, các lực lượng nước ngoài và chiến tranh tái diễn. Kháng chiến chống thực dân Pháp kết thúc bằng chiến thắng Điện Biên Phủ và Hiệp định Genève năm 1954, nhưng đất nước bị chia cắt trong một trật tự quốc tế căng thẳng. Giai đoạn 1954–1975 gồm những chiến lược, lực lượng, đời sống dân sự, ngoại giao và chiến trường khác nhau; không thể chỉ kể bằng bản đồ chiến dịch. Học sinh cần tách mốc, chủ thể, mục tiêu, nguồn lực, trải nghiệm của dân thường và hệ quả lâu dài. Các văn kiện chính trị có giá trị để hiểu đường lối và ngôn ngữ của nhà nước, song cần đọc cùng hồi ký, tư liệu quốc tế, hiện vật và nghiên cứu về nạn nhân. Khi nhắc thắng lợi, phải đồng thời nói về hy sinh, di dời, thương tật, hậu quả môi trường và nỗ lực hòa giải. Bài học không cổ súy chiến tranh; nó giúp hiểu vì sao độc lập, thống nhất và bảo vệ Tổ quốc được xem là mục tiêu lịch sử, đồng thời nuôi dưỡng trách nhiệm hòa bình."+suffixVi,learningObjectives:["Phân tích các chặng chính từ Cách mạng tháng Tám đến 1975.","Kết nối chính trị, quân sự, ngoại giao và trải nghiệm dân sự.","Đánh giá nguồn và hậu quả chiến tranh với thái độ nhân văn."],originalSummary:"Lịch sử 1945–1975 là quá trình cách mạng, chiến tranh, ngoại giao và chịu đựng của xã hội hướng tới độc lập và thống nhất.",analysis:"Một câu chuyện chính trị không được xóa đời sống dân sự; mọi tuyên bố về thành công cần ghi nguồn và giới hạn diễn giải.",debates:[{title:"Có thể hiểu 1945–1975 chỉ bằng lịch sử quân sự không?",summary:"Quân sự là một lớp quan trọng nhưng phải đọc cùng ngoại giao, kinh tế, xã hội, văn hóa, dân sự và ký ức hậu chiến.",claimIds:["claim-g12-august-outcome","claim-g12-war-geneva"]}]},en:{title:"Revolution, wars of independence, and national defence, 1945–1975",slug:"revolution-wars-of-independence-and-national-defence-1945-1975",summary:"From the August Revolution to reunification, political, military, diplomatic, and social upheaval brought immense losses.",body:"The August Revolution of 1945 led to the Democratic Republic of Vietnam amid Japan's surrender, colonial crisis, and revolutionary mobilisation and popular uprisings. The new state faced famine, scarcity, foreign forces, and renewed war. The war against French colonial rule ended with Dien Bien Phu and the 1954 Geneva Agreement, while the country was divided within a tense international order. From 1954 to 1975, strategies, forces, civilian life, diplomacy, and battlefields differed; the period cannot be told only through campaign maps. Students separate dates, actors, aims, resources, civilian experiences, and long-term consequences. Political documents reveal state language and policy, but should be read with memoirs, international records, objects, and victim-centred research. When discussing victory, also discuss sacrifice, displacement, disability, environmental effects, and reconciliation. The lesson does not glorify war; it studies why independence, reunification, and defence mattered while cultivating peace."+suffixEn,learningObjectives:["Analyse major stages from the August Revolution to 1975.","Connect politics, military affairs, diplomacy, and civilian experience.","Evaluate sources and war consequences humanely."],originalSummary:"1945–1975 combines revolution, war, diplomacy, and social endurance toward independence and reunification.",analysis:"Political narrative cannot erase civilian life; every success claim needs a source and interpretive limit."+reviewEn,debates:[{title:"Can 1945–1975 be understood through military history alone?",summary:"Military history is important but must be read with diplomacy, economy, society, culture, civilians, and memory.",claimIds:["claim-g12-august-outcome","claim-g12-war-geneva"]}]},claims:[{id:"claim-g12-august-outcome",claimType:"DATE",assessment:"CONFIRMED",statementVi:"Tư liệu Văn kiện Đảng ghi Cách mạng tháng Tám năm 1945 và ngày 2/9/1945 tuyên bố sự ra đời của nước Việt Nam Dân chủ Cộng hòa.",statementEn:"Party archival material records the August Revolution of 1945 and the 2 September 1945 declaration of the Democratic Republic of Vietnam.",sourceId:"source-g12-august-revolution",locator:"Cách mạng Tháng 8 và Quốc khánh 2/9/1945 — event chronology",note:"Claim mô tả nguồn hồi cố chính thức và không thay thế nguồn đương thời."},{id:"claim-g12-war-geneva",claimType:"CONTEXT",assessment:"CONFIRMED",statementVi:"Biên niên Đảng đặt Điện Biên Phủ và Hiệp định Genève trong tiến trình kháng chiến chống Pháp và tái lập hòa bình ở Đông Dương.",statementEn:"The Party chronology places Dien Bien Phu and the Geneva Agreement within the war against French colonial rule and the restoration of peace in Indochina.",sourceId:"source-g12-party-chronology",locator:"Lịch sử Biên niên Đảng — entries on Dien Bien Phu and Geneva",note:"Claim nêu cách nguồn tổ chức câu chuyện, không loại bỏ các nguồn quốc tế khác."}]},
 {id:"lesson-g12-vietnam-since-1975",requirementId:"g12-vietnam-since-1975",track:"MANDATORY",sourceIds:["source-g12-moet-programme","source-g12-doimoi","source-g12-gso-development"],vi:{title:"Việt Nam từ năm 1975 đến nay và công cuộc Đổi mới",slug:"viet-nam-tu-nam-1975-den-nay-va-cong-cuoc-doi-moi",summary:"Sau 1975, Việt Nam tái thiết, bảo vệ Tổ quốc và Đổi mới; cập nhật hiện tại phải có asOf, chỉ số và nguồn gốc dữ liệu.",body:"Sau năm 1975, Việt Nam đối mặt với tái thiết, thống nhất quản lý, khó khăn kinh tế, bảo vệ biên giới và nhu cầu điều chỉnh chính sách. Công cuộc Đổi mới từ năm 1986 không phải một khoảnh khắc đơn lẻ mà là quá trình thay đổi cơ chế quản lý, sản xuất, đối ngoại, giáo dục và đời sống qua nhiều giai đoạn. Một chính sách có thể tạo tăng trưởng và cơ hội nhưng cũng phát sinh chênh lệch, di cư, áp lực môi trường và nhóm bị bỏ lại; đánh giá cần dùng số liệu lẫn tiếng nói xã hội. Cổng thông tin Chính phủ cung cấp diễn giải chính sách, còn Tổng cục Thống kê cung cấp dữ liệu cần ghi định nghĩa, năm và phương pháp. Học sinh nên phân biệt mục tiêu Đổi mới, công cụ, kết quả đo được và trải nghiệm chưa được thống kê. “Đến nay” không phải một kết luận vô hạn: bài này có asOf 13/08/2026 và phải cập nhật khi dữ liệu đổi. Khi đọc số liệu GDP, nghèo, dân số hoặc thương mại, không suy ra nguyên nhân duy nhất từ một đường biểu diễn. Lịch sử từ 1975 cũng gồm ký ức chiến tranh, hòa giải, văn hóa và quyền công dân; tránh ngôn ngữ phủ nhận đau khổ hoặc tự động đồng nhất phát triển với hạnh phúc. Mục tiêu là hiểu một quá trình chính sách có thành tựu, chi phí và khả năng sửa chữa."+suffixVi,learningObjectives:["Trình bày những vấn đề tái thiết và bảo vệ Tổ quốc sau 1975.","Phân tích Đổi mới như một quá trình chính sách nhiều giai đoạn.","Đọc số liệu hiện tại với asOf, định nghĩa và giới hạn."],originalSummary:"Đổi mới là quá trình điều chỉnh lâu dài, cần đọc cùng thành tựu, chênh lệch, dữ liệu và trải nghiệm xã hội.",analysis:"Mọi cập nhật hiện tại phải có asOf và nguồn; thống kê mô tả xu hướng nhưng không tự giải thích nguyên nhân hay giá trị sống.",debates:[{title:"Tăng trưởng có đồng nghĩa phát triển công bằng không?",summary:"Tăng trưởng là một chỉ dấu; cần đối chiếu phân phối, môi trường, dịch vụ công và tiếng nói nhóm khác nhau.",claimIds:["claim-g12-doimoi-process","claim-g12-current-data"]}]},en:{title:"Vietnam since 1975 and the Đổi mới process",slug:"vietnam-since-1975-and-the-doi-moi-process",summary:"After 1975 Vietnam rebuilt, defended the country, and pursued Đổi mới; current updates require an as-of date, indicators, and data provenance.",body:"After 1975 Vietnam faced reconstruction, administrative reunification, economic difficulty, border defence, and pressure to adjust policy. Đổi mới from 1986 was not one moment but a process changing management, production, foreign relations, education, and daily life across stages. A policy can create growth and opportunity while also producing inequality, migration, environmental pressure, and groups left behind; assessment needs statistics and social voices. Government policy explanations and General Statistics Office data have different purposes, and every indicator needs a definition, year, and method. Students distinguish Đổi mới goals, instruments, measured outcomes, and experiences not captured by statistics. ‘To the present’ is not an unlimited conclusion: this lesson is as of 13 August 2026 and must be updated when data changes. GDP, poverty, population, or trade series cannot prove a single cause. Post-1975 history includes war memory, reconciliation, culture, and citizenship; avoid denying suffering or equating development automatically with happiness. The aim is to understand a policy process with achievements, costs, and capacity to adjust."+suffixEn,learningObjectives:["Outline reconstruction and national defence after 1975.","Analyse Đổi mới as a multi-stage policy process.","Read current data with an as-of date, definition, and limits."],originalSummary:"Đổi mới is a long process of adjustment that must be read with achievements, inequality, data, and social experience.",analysis:"Every current update needs an as-of date and source; statistics describe trends but do not explain causes or well-being by themselves."+reviewEn,debates:[{title:"Does growth equal equitable development?",summary:"Growth is one indicator; compare distribution, environment, public services, and different voices.",claimIds:["claim-g12-doimoi-process","claim-g12-current-data"]}]},claims:[{id:"claim-g12-doimoi-process",claimType:"CONTEXT",assessment:"CONFIRMED",statementVi:"Nguồn của Cổng thông tin Chính phủ trình bày Đổi mới như quá trình đổi mới quản lý và phát triển đất nước, không chỉ một mốc duy nhất.",statementEn:"A Government Portal source presents Đổi mới as a process of changing management and national development rather than one isolated date.",sourceId:"source-g12-doimoi",locator:"Đổi mới và phát triển kinh tế Việt Nam — policy overview",note:"Claim ghi rõ loại nguồn chính sách và cần đối chiếu dữ liệu độc lập."},{id:"claim-g12-current-data",claimType:"CONTEXT",assessment:"CONFIRMED",statementVi:"Số liệu hiện tại chỉ có ý nghĩa khi ghi định nghĩa, năm và ngày cập nhật; bài C-034 có asOf 13/08/2026.",statementEn:"Current statistics are meaningful only with a definition, year, and update date; the C-034 lesson is as of 13 August 2026.",sourceId:"source-g12-gso-development",locator:"GSO data portal — definitions and year-specific tables",note:"Claim là quy tắc provenance cho cập nhật, không nêu một chỉ số cụ thể."}]},
 {id:"lesson-g12-foreign-relations",requirementId:"g12-vietnamese-foreign-relations",track:"MANDATORY",sourceIds:["source-g12-moet-programme","source-g12-mofa-foreign-policy","source-g12-foreign-relations-timeline"],vi:{title:"Lịch sử đối ngoại Việt Nam thời cận – hiện đại",slug:"lich-su-doi-ngoai-viet-nam-thoi-can-hien-dai",summary:"Đối ngoại Việt Nam biến đổi qua chiến tranh, độc lập, hội nhập và các nguyên tắc bảo vệ lợi ích quốc gia bằng hòa bình và luật pháp.",body:"Lịch sử đối ngoại Việt Nam thời cận–hiện đại là lịch sử của quan hệ giữa chủ quyền, an ninh, kinh tế, văn hóa và trật tự quốc tế. Từ thời thuộc địa, qua 1945, các cuộc kháng chiến, thống nhất và Đổi mới, nhà nước phải xử lý nhiều đối tác, bất cân xứng quyền lực và mục tiêu vừa bảo vệ độc lập vừa mở rộng hợp tác. Một công hàm, hiệp định hoặc tuyên bố là nguồn có người ký, thẩm quyền, ngôn ngữ và mục đích; không nên trích một câu ngoài bối cảnh để kết luận toàn bộ quan hệ. Bộ Ngoại giao cung cấp diễn giải chính sách và cổng quan hệ, nhưng học sinh cần phân biệt nguồn chính sách với nghiên cứu của bên thứ ba, văn kiện quốc tế và trải nghiệm xã hội. Các mốc hội nhập kinh tế, ngoại giao đa phương và quan hệ láng giềng nên được lập timeline có asOf. Đối ngoại không chỉ là hoạt động của lãnh đạo: doanh nghiệp, người Việt ở nước ngoài, văn hóa, giáo dục và cộng đồng biên giới cũng tham gia. Khi đánh giá một lựa chọn, hỏi lợi ích, rủi ro, tiếng nói được đại diện và nguyên tắc luật quốc tế. Bài học khuyến khích tôn trọng chủ quyền, đối thoại và hợp tác, không kích động dân tộc chủ nghĩa hay coi mọi bất đồng là thù địch. Lịch sử đối ngoại giúp học sinh hiểu “hòa hiếu” như năng lực chiến lược có bằng chứng, không phải khẩu hiệu."+suffixVi,learningObjectives:["Phân tích các giai đoạn và nguyên tắc đối ngoại Việt Nam.","Đọc hiệp định, tuyên bố và thông cáo trong bối cảnh thẩm quyền.","Đánh giá quan hệ đối ngoại bằng lợi ích, rủi ro và luật quốc tế."],originalSummary:"Đối ngoại nối chủ quyền với hợp tác; lịch sử của nó gồm văn kiện, con người, bất cân xứng và lựa chọn hòa bình.",analysis:"Nguồn của Bộ Ngoại giao có giá trị về lập trường chính sách nhưng phải ghi đúng vị trí phát ngôn và đối chiếu khi claim mang tính lịch sử.",debates:[{title:"Đối ngoại có chỉ là quan hệ giữa các chính phủ không?",summary:"Nhà nước giữ vai trò trung tâm nhưng thương mại, văn hóa, giáo dục và cộng đồng cũng tạo quan hệ quốc tế.",claimIds:["claim-g12-foreign-principles","claim-g12-foreign-asof"]}]},en:{title:"Vietnamese foreign relations in modern history",slug:"vietnamese-foreign-relations-in-modern-history",summary:"Vietnamese foreign relations changed through war, independence, integration, and peaceful protection of national interests under law.",body:"Modern Vietnamese foreign-relations history connects sovereignty, security, economy, culture, and international order. From colonial rule through 1945, wars, reunification, and Đổi mới, the state handled multiple partners, unequal power, and the need to protect independence while expanding cooperation. A diplomatic note, agreement, or statement has a signatory, authority, language, and purpose; a sentence outside context cannot represent an entire relationship. The Ministry of Foreign Affairs provides policy explanations and a relations portal, while students distinguish policy sources from third-party research, international documents, and social experience. Economic integration, multilateral diplomacy, and neighbour relations should be placed on an as-of timeline. Foreign relations are not only leaders' activity: businesses, overseas Vietnamese, culture, education, and border communities participate. Evaluate choices by interests, risks, represented voices, and international law. The lesson supports sovereignty, dialogue, and cooperation, never chauvinism or treating every disagreement as hostility. Foreign-relations history makes peaceful strategy a question of evidence, not a slogan."+suffixEn,learningObjectives:["Analyse stages and principles of Vietnamese foreign relations.","Read agreements, statements, and communiques in authority context.","Evaluate relations through interests, risks, and international law."],originalSummary:"Foreign relations connect sovereignty and cooperation through documents, people, unequal power, and peaceful choices.",analysis:"A Foreign Ministry source is valuable for policy position but must be labelled as such and cross-checked when a claim is historical."+reviewEn,debates:[{title:"Are foreign relations only government-to-government relations?",summary:"States are central, but trade, culture, education, and communities also create international relations.",claimIds:["claim-g12-foreign-principles","claim-g12-foreign-asof"]}]},claims:[{id:"claim-g12-foreign-principles",claimType:"CONTEXT",assessment:"CONFIRMED",statementVi:"Bộ Ngoại giao trình bày đối ngoại hướng tới lợi ích quốc gia–dân tộc, hòa bình, ổn định và tôn trọng luật pháp quốc tế.",statementEn:"The Foreign Ministry describes foreign affairs as pursuing national interests, peace, stability, and respect for international law.",sourceId:"source-g12-mofa-foreign-policy",locator:"Đẩy mạnh đối ngoại toàn diện — stated principles and objectives",note:"Claim ghi rõ đây là lập trường chính sách của cơ quan phát ngôn."},{id:"claim-g12-foreign-asof",claimType:"CONTEXT",assessment:"CONFIRMED",statementVi:"Cổng quan hệ đối ngoại là đầu mối cập nhật, nên mọi bài sử dụng nó phải ghi ngày truy cập và asOf.",statementEn:"The foreign-relations portal is an updating gateway, so any lesson using it must record an access date and as-of value.",sourceId:"source-g12-foreign-relations-timeline",locator:"MOFA foreign-relations portal — current gateway and dated entries",note:"Claim là quy tắc provenance, không coi trang cổng là một chuyên khảo."}]},
 {id:"lesson-g12-ho-chi-minh",requirementId:"g12-ho-chi-minh",track:"MANDATORY",sourceIds:["source-g12-moet-programme","source-g12-ho-chi-minh-documents","source-g12-hcm-museum"],vi:{title:"Hồ Chí Minh trong lịch sử Việt Nam",slug:"ho-chi-minh-trong-lich-su-viet-nam",summary:"Hồ Chí Minh cần được nghiên cứu qua hoạt động, văn bản, mạng lưới và ký ức; tôn trọng di sản không đồng nghĩa bỏ qua phương pháp lịch sử.",body:"Hồ Chí Minh là một nhân vật trung tâm của lịch sử Việt Nam thế kỉ XX, được nghiên cứu qua nhiều lớp nguồn: văn bản chính trị, thư từ, hồi ký, ảnh, hiện vật, tư liệu quốc tế và ký ức cộng đồng. Hành trình hoạt động của ông gắn với chủ nghĩa thực dân, phong trào giải phóng dân tộc, quan hệ Việt Nam–Lào và việc thành lập nhà nước sau 1945. Một bài học có trách nhiệm phải tách điều nhân vật tự viết, điều đồng sự ghi lại, điều cơ quan tưởng niệm diễn giải và điều nghiên cứu sau này tranh luận. Không nên thần thánh hóa, cũng không dùng tiêu chuẩn hiện tại đơn giản để phủ định bối cảnh. Học sinh có thể lập timeline các giai đoạn, ghi người tạo nguồn, mục đích, ngôn ngữ và khoảng trống; sau đó so sánh một văn bản với một hiện vật hoặc hồi ký. Vai trò lãnh đạo cần được đặt cạnh tổ chức, quần chúng, đồng chí, quốc tế và những người bị che khuất trong hồ sơ. Bảo tàng giúp công chúng tiếp cận di sản nhưng trưng bày là một lựa chọn diễn giải, không phải toàn bộ quá khứ. Nội dung về Hồ Chí Minh phải tôn trọng nhân phẩm, gia đình, bản quyền ảnh và sự đa dạng của người học. Mục tiêu là hiểu vai trò lịch sử bằng chứng cứ, không biến bài học thành khẩu hiệu hay tranh cãi cá nhân."+suffixVi,learningObjectives:["Trình bày các giai đoạn hoạt động và vai trò lịch sử của Hồ Chí Minh.","Phân tích văn bản, hiện vật, hồi ký và ký ức như các loại nguồn khác nhau.","Đánh giá nhân vật trong bối cảnh, mạng lưới và giới hạn chứng cứ."],originalSummary:"Hồ Chí Minh được hiểu qua hoạt động và mạng lưới lịch sử, văn bản và ký ức, với phương pháp tách nguồn khỏi huyền thoại.",analysis:"Tôn trọng nhân vật và di sản phải đi cùng quyền được kiểm chứng; mỗi trích dẫn cần xác định tác giả, thời điểm và loại nguồn.",debates:[{title:"Có thể tách một nhân vật khỏi mạng lưới xã hội không?",summary:"Lãnh đạo có vai trò nhưng thành tựu lịch sử do tổ chức, quần chúng, đồng minh và hoàn cảnh cùng tạo nên.",claimIds:["claim-g12-hcm-activity","claim-g12-hcm-method"]}]},en:{title:"Hồ Chí Minh in Vietnamese history",slug:"ho-chi-minh-in-vietnamese-history",summary:"Ho Chi Minh should be studied through activity, documents, networks, and memory; respect for heritage does not replace historical method.",body:"Ho Chi Minh is a central figure in twentieth-century Vietnamese history, studied through political texts, letters, memoirs, photographs, objects, international records, and community memory. His activities connect colonialism, national liberation, Vietnam–Laos relations, and the formation of the post-1945 state. A responsible lesson separates what he wrote, what associates recorded, what commemorative institutions interpret, and what later scholarship debates. It should neither mythologise nor use a simplistic present-day standard to erase context. Students build a timeline with maker, purpose, language, and absences, then compare a text with an object or memoir. Leadership belongs beside organisation, mass participation, colleagues, international partners, and people missing from records. A museum makes heritage accessible but its display is an interpretive choice, not the whole past. Ho Chi Minh content must respect dignity, family, image rights, and diverse learners. The goal is evidence-based historical understanding rather than slogan or personal polemic."+suffixEn,learningObjectives:["Outline Ho Chi Minh's activities and historical role.","Analyse texts, objects, memoirs, and memory as different source types.","Assess a figure within context, networks, and evidentiary limits."],originalSummary:"Ho Chi Minh is understood through historical activity, networks, documents, and memory, with sources separated from legend.",analysis:"Respect for a figure and heritage belongs with the right to verify; every quotation identifies author, date, and source type."+reviewEn,debates:[{title:"Can a historical figure be separated from social networks?",summary:"Leadership matters, but organisations, people, allies, and circumstances also create historical outcomes.",claimIds:["claim-g12-hcm-activity","claim-g12-hcm-method"]}]},claims:[{id:"claim-g12-hcm-activity",claimType:"CONTEXT",assessment:"CONFIRMED",statementVi:"Tư liệu về Hồ Chí Minh với cách mạng Lào trình bày hoạt động quốc tế và mối liên hệ với phong trào giải phóng dân tộc.",statementEn:"Material on Ho Chi Minh and the Lao revolution presents international activity and connections with national liberation movements.",sourceId:"source-g12-ho-chi-minh-documents",locator:"Hồ Chí Minh với cách mạng Lào — sections on 1945 and international solidarity",note:"Claim chỉ dùng phạm vi bài tư liệu, không đại diện toàn bộ sự nghiệp."},{id:"claim-g12-hcm-method",claimType:"INTERPRETATION",assessment:"CONFIRMED",statementVi:"Hồ sơ nhân vật phải đối chiếu văn bản, hiện vật, hồi ký và ký ức với người tạo và mục đích riêng.",statementEn:"A figure profile should compare texts, objects, memoirs, and memory with each source's maker and purpose.",sourceId:"source-g12-hcm-museum",locator:"Bảo tàng Hồ Chí Minh — museum portal and collections context",note:"Claim là nguyên tắc provenance, không gán một trưng bày là toàn bộ lịch sử."}]},
 {id:"lesson-g12-religion",requirementId:"g12-belief-and-religion-vietnam",track:"ELECTIVE",sourceIds:["source-g12-moet-programme","source-g12-religion-heritage"],vi:{title:"Chuyên đề lựa chọn: tín ngưỡng và tôn giáo ở Việt Nam",slug:"chuyen-de-tin-nguong-va-ton-giao-o-viet-nam",summary:"Tín ngưỡng và tôn giáo là những thực hành đa dạng gắn với cộng đồng, thiết chế, di sản và biến đổi xã hội.",body:"Lịch sử tín ngưỡng và tôn giáo ở Việt Nam gồm thờ cúng tổ tiên, tín ngưỡng dân gian, Phật giáo, Nho giáo, Đạo giáo, Công giáo, Hồi giáo và các thực hành mới. Các truyền thống không tồn tại biệt lập: chúng giao thoa, được địa phương hóa và thay đổi theo gia đình, làng xã, đô thị, nhà nước và giao lưu quốc tế. Học sinh cần phân biệt tín ngưỡng, tôn giáo, nghi lễ, niềm tin cá nhân và di sản được nhà nước hoặc tổ chức quốc tế ghi danh. UNESCO nhấn mạnh vai trò của cộng đồng thực hành; danh mục di sản không thể thay thế tiếng nói của người sống với nghi lễ. Khi nghiên cứu một lễ hội, hãy hỏi ai tổ chức, ai tham dự, ai bị loại trừ, kinh phí đến đâu và ý nghĩa có thay đổi không. Không dùng nhãn “mê tín” để phủ định một cộng đồng, cũng không lãng mạn hóa mọi thực hành. Nguồn tôn giáo, sắc phong, văn bia, hồi ký, khảo sát dân tộc học và quan sát hiện tại có mục đích khác nhau; phỏng vấn cần đồng thuận và bảo vệ riêng tư. Đây là elective, không làm tăng coverage mandatory lớp 12. Bài học khuyến khích hiểu khác biệt, quyền tự do tín ngưỡng và trách nhiệm chống kỳ thị."+suffixVi,learningObjectives:["Nhận diện sự đa dạng của tín ngưỡng và tôn giáo ở Việt Nam.","Phân tích sự biến đổi của thực hành trong cộng đồng và thiết chế.","Nghiên cứu di sản tôn trọng quyền, riêng tư và chống kỳ thị."],originalSummary:"Tín ngưỡng và tôn giáo là lịch sử sống của cộng đồng, luôn giao thoa và biến đổi.",analysis:"Không được dùng một nhãn hành chính hoặc phán xét đạo đức để thay thế mô tả và tiếng nói người thực hành.",debates:[{title:"Ghi danh di sản có làm thực hành sống bất biến không?",summary:"Danh hiệu có thể hỗ trợ bảo tồn nhưng cũng đóng khung; cần theo dõi sự thay đổi và quyền cộng đồng.",claimIds:["claim-g12-religion-community","claim-g12-religion-change"]}]},en:{title:"Elective: belief and religion in Vietnam",slug:"elective-belief-and-religion-in-vietnam",summary:"Belief and religion are diverse practices connected to communities, institutions, heritage, and social change.",body:"Vietnamese religious and belief history includes ancestor worship, folk practices, Buddhism, Confucianism, Daoism, Christianity, Islam, and newer practices. Traditions were not isolated: they mixed, localised, and changed through families, villages, cities, states, and international exchange. Students distinguish belief, religion, ritual, personal faith, and heritage designation. UNESCO emphasises practitioner communities; a heritage inventory cannot replace people who live the ritual. For a festival, ask who organises, participates, is excluded, pays, and how meaning changes. Do not use ‘superstition’ to dismiss a community, nor romanticise every practice. Religious records, titles, inscriptions, memoirs, ethnography, and present observation have different purposes; interviews need consent and privacy. This elective does not increase Grade 12 mandatory coverage. It supports understanding difference, freedom of belief, and anti-discrimination."+suffixEn,learningObjectives:["Identify diversity of belief and religion in Vietnam.","Analyse change in practices, communities, and institutions.","Research heritage with rights, privacy, and anti-discrimination."],originalSummary:"Belief and religion are living community histories that mix and change.",analysis:"An administrative label or moral judgement cannot replace description and practitioners' voices."+reviewEn,debates:[{title:"Does heritage listing freeze a living practice?",summary:"Recognition can support safeguarding but also frame a practice; monitor change and community rights.",claimIds:["claim-g12-religion-community","claim-g12-religion-change"]}]},claims:[{id:"claim-g12-religion-community",claimType:"CONTEXT",assessment:"CONFIRMED",statementVi:"UNESCO mô tả di sản phi vật thể gắn với cộng đồng và người thực hành, phù hợp với cách nghiên cứu tín ngưỡng có quyền.",statementEn:"UNESCO presents intangible heritage as connected to communities and practitioners, supporting a rights-aware study of belief.",sourceId:"source-g12-religion-heritage",locator:"UNESCO Intangible Cultural Heritage — Viet Nam state page",note:"Claim là nguyên tắc cộng đồng, không gán toàn bộ tôn giáo Việt Nam vào một danh mục."},{id:"claim-g12-religion-change",claimType:"INTERPRETATION",assessment:"CONFIRMED",statementVi:"Nghiên cứu nghi lễ cần theo dõi biến đổi, người tham gia và điều kiện xã hội thay vì xem truyền thống bất biến.",statementEn:"Ritual research should trace change, participants, and social conditions rather than treating tradition as fixed.",sourceId:"source-g12-moet-programme",locator:"Chuyên đề lựa chọn lớp 12 — yêu cầu thực hành và tìm hiểu văn hóa",note:"Claim là khung phương pháp học tập."}]},
 {id:"lesson-g12-japan",requirementId:"g12-japan-since-1945",track:"ELECTIVE",sourceIds:["source-g12-moet-programme","source-g12-japan-1945","source-g12-un-cold-war"],vi:{title:"Chuyên đề lựa chọn: Nhật Bản từ năm 1945 đến nay",slug:"chuyen-de-nhat-ban-tu-nam-1945-den-nay",summary:"Nhật Bản sau 1945 phục hồi và phát triển trong liên minh, cải cách, công nghệ và các tranh luận xã hội.",body:"Nhật Bản sau 1945 trải qua chiếm đóng, cải cách thể chế, tái thiết, tăng trưởng nhanh, khủng hoảng và điều chỉnh xã hội. Con đường này thường được gọi là “kỳ tích” nhưng không nên tách khỏi lao động, giới, môi trường, thuộc địa ký ức, bất bình đẳng và quan hệ an ninh. Các sách trắng ngoại giao và nguồn chính phủ Nhật cho biết lập trường chính thức; để hiểu xã hội cần thêm thống kê, hồi ký, nghiên cứu địa phương và tiếng nói người chịu tác động. Học sinh có thể so sánh tăng trưởng công nghiệp, đô thị hóa, giáo dục, già hóa dân số và thay đổi vai trò quốc tế qua các giai đoạn. Không dùng Nhật Bản làm khuôn mẫu bắt buộc cho Việt Nam: bối cảnh chiến tranh, thể chế, dân số và quan hệ quốc tế khác nhau. Bài học cũng cần nói về ký ức chiến tranh và cách lịch sử được tranh luận ở trường học, bảo tàng và ngoại giao. Đây là elective, tách khỏi mandatory coverage; mục tiêu là so sánh có điều kiện, tôn trọng nguồn và tránh xếp hạng văn minh."+suffixVi,learningObjectives:["Phân tích tái thiết, tăng trưởng và điều chỉnh của Nhật Bản sau 1945.","Đọc nguồn chính sách cùng dữ liệu và trải nghiệm xã hội.","So sánh Nhật Bản với Việt Nam mà không áp mô hình tuyến tính."],originalSummary:"Nhật Bản sau 1945 là lịch sử phục hồi và phát triển cùng những chi phí, ký ức và điều chỉnh.",analysis:"“Kỳ tích” là một khung diễn giải, không phải dữ kiện đủ; cần nêu ai hưởng lợi và điều gì bị che khuất.",debates:[{title:"Mô hình Nhật Bản có thể sao chép nguyên vẹn không?",summary:"Chính sách chỉ hoạt động trong điều kiện lịch sử và thể chế cụ thể; so sánh phải nêu khác biệt.",claimIds:["claim-g12-japan-recovery","claim-g12-japan-limits"]}]},en:{title:"Elective: Japan since 1945",slug:"elective-japan-since-1945",summary:"Post-1945 Japan combined recovery, reform, technology, alliance, and social debate.",body:"Japan after 1945 experienced occupation, institutional reform, reconstruction, rapid growth, crisis, and social adjustment. Often called an ‘economic miracle’, this path must also include labour, gender, environment, colonial memory, inequality, and security relations. Japanese diplomatic and government sources reveal official positions; statistics, memoirs, local research, and affected voices help study society. Students compare industrial growth, urbanisation, education, ageing, and international role across periods. Japan is not a template to impose on Vietnam: war, institutions, population, and international settings differ. The lesson includes war memory and how history is debated in schools, museums, and diplomacy. As an elective, it is separate from mandatory coverage; the goal is conditional comparison and respect for sources, not civilisational ranking."+suffixEn,learningObjectives:["Analyse Japan's reconstruction, growth, and adjustment after 1945.","Read policy sources with data and social experience.","Compare Japan and Vietnam without a linear model."],originalSummary:"Post-1945 Japan is a history of recovery and development with costs, memory, and adjustment.",analysis:"‘Miracle’ is an interpretive frame, not sufficient fact; state who benefited and what it hides."+reviewEn,debates:[{title:"Can the Japanese model be copied intact?",summary:"Policies operate in specific historical and institutional conditions; comparison must name differences.",claimIds:["claim-g12-japan-recovery","claim-g12-japan-limits"]}]},claims:[{id:"claim-g12-japan-recovery",claimType:"CONTEXT",assessment:"CONFIRMED",statementVi:"Nguồn ngoại giao Nhật Bản cung cấp khung chính thức để đọc quá trình Nhật Bản sau 1945, cần đối chiếu với nguồn xã hội.",statementEn:"Japanese diplomatic sources provide an official frame for studying Japan after 1945 and should be compared with social sources.",sourceId:"source-g12-japan-1945",locator:"MOFA Diplomatic Bluebook — post-war diplomacy and development sections",note:"Claim ghi rõ vị trí và giới hạn của nguồn nhà nước."},{id:"claim-g12-japan-limits",claimType:"INTERPRETATION",assessment:"CONFIRMED",statementVi:"So sánh Nhật Bản với Việt Nam phải ghi điều kiện khác nhau về chiến tranh, thể chế, dân số và quan hệ quốc tế.",statementEn:"Comparisons between Japan and Vietnam must state differences in war, institutions, population, and international relations.",sourceId:"source-g12-un-cold-war",locator:"UN post-war history — international context for comparative framing",note:"Claim là nguyên tắc so sánh, không phải kết luận định lượng."}]},
 {id:"lesson-g12-integration",requirementId:"g12-vietnam-international-integration",track:"ELECTIVE",sourceIds:["source-g12-moet-programme","source-g12-mofa-foreign-policy","source-g12-gso-development"],vi:{title:"Chuyên đề lựa chọn: quá trình hội nhập quốc tế của Việt Nam",slug:"chuyen-de-qua-trinh-hoi-nhap-quoc-te-cua-viet-nam",summary:"Hội nhập quốc tế mở ra hợp tác và cơ hội nhưng cũng tạo phụ thuộc, cạnh tranh và yêu cầu năng lực thích ứng.",body:"Hội nhập quốc tế của Việt Nam diễn ra qua ngoại giao, thương mại, đầu tư, giáo dục, văn hóa, khoa học và các thể chế đa phương. Từ Đổi mới, mở rộng quan hệ giúp Việt Nam tiếp cận thị trường, công nghệ, tri thức và hợp tác an ninh; đồng thời nền kinh tế và xã hội phải xử lý cạnh tranh, tiêu chuẩn, chuỗi cung ứng, bất bình đẳng và rủi ro xuyên biên giới. Bộ Ngoại giao trình bày mục tiêu lợi ích quốc gia, hòa bình và đóng góp quốc tế, còn dữ liệu thống kê cho biết một số chỉ dấu cần định nghĩa. Học sinh nên lập timeline các mốc gia nhập, hiệp định, diễn đàn và thay đổi xã hội, ghi asOf cho mỗi cập nhật. Không đánh đồng ký một hiệp định với lợi ích tự động đến mọi người; cần hỏi ngành nào, vùng nào và nhóm nào chịu chi phí. Hội nhập cũng không có nghĩa từ bỏ bản sắc hay chủ quyền; đó là năng lực tham gia có lựa chọn, bảo vệ luật pháp và lợi ích hợp pháp. Đây là elective, giúp sinh viên phân tích chính sách hiện tại bằng lịch sử, dữ liệu và tiếng nói cộng đồng, không phải bài tuyên truyền thành tích."+suffixVi,learningObjectives:["Trình bày các giai đoạn và lĩnh vực hội nhập quốc tế.","Phân tích cơ hội, chi phí và năng lực thích ứng của xã hội.","Đọc cập nhật chính sách và dữ liệu với asOf, nguồn và giới hạn."],originalSummary:"Hội nhập là lựa chọn có quản trị giữa hợp tác, cơ hội, cạnh tranh và rủi ro.",analysis:"Không dùng một chỉ số thương mại để đại diện cho toàn xã hội; cần đối chiếu chính sách, dữ liệu và trải nghiệm người dân.",debates:[{title:"Hội nhập có làm mất quyền tự chủ không?",summary:"Phụ thuộc và tự chủ thay đổi theo lĩnh vực; năng lực đàm phán, đa dạng hóa và luật pháp quyết định kết quả.",claimIds:["claim-g12-integration-policy","claim-g12-integration-data"]}]},en:{title:"Elective: Vietnam's international integration",slug:"elective-vietnams-international-integration",summary:"International integration creates cooperation and opportunity while also bringing dependence, competition, and adaptation demands.",body:"Vietnam's international integration spans diplomacy, trade, investment, education, culture, science, and multilateral institutions. Since Đổi mới, expanded relations brought markets, technology, knowledge, and security cooperation, while society addressed competition, standards, supply chains, inequality, and cross-border risks. Foreign Ministry policy sources state national-interest and peace goals; statistics provide indicators that need definitions. Students build a timeline of accessions, agreements, forums, and social changes, recording an as-of date for each update. Signing an agreement does not automatically benefit everyone: ask which sectors, regions, and groups gain or bear costs. Integration does not mean abandoning identity or sovereignty; it is selective participation with law and legitimate interests. This elective helps students analyse current policy through history, data, and community voices rather than a catalogue of achievements."+suffixEn,learningObjectives:["Outline stages and fields of international integration.","Analyse social opportunities, costs, and adaptation capacity.","Read policy updates and data with as-of, sources, and limits."],originalSummary:"Integration is a governed choice among cooperation, opportunity, competition, and risk.",analysis:"One trade indicator cannot represent society; compare policy, data, and people's experience."+reviewEn,debates:[{title:"Does integration remove autonomy?",summary:"Dependence and autonomy vary by field; negotiation, diversification, and law shape outcomes.",claimIds:["claim-g12-integration-policy","claim-g12-integration-data"]}]},claims:[{id:"claim-g12-integration-policy",claimType:"CONTEXT",assessment:"CONFIRMED",statementVi:"Bộ Ngoại giao đặt hội nhập trong mục tiêu lợi ích quốc gia–dân tộc, hòa bình, ổn định và đóng góp quốc tế.",statementEn:"The Foreign Ministry places integration within national interests, peace, stability, and international contribution.",sourceId:"source-g12-mofa-foreign-policy",locator:"Đẩy mạnh đối ngoại toàn diện — integration, peace, and national-interest objectives",note:"Claim được gắn nhãn lập trường chính sách và cần cập nhật asOf."},{id:"claim-g12-integration-data",claimType:"CONTEXT",assessment:"CONFIRMED",statementVi:"Đánh giá hội nhập cần kết hợp chỉ số kinh tế với phân phối lợi ích, chi phí và trải nghiệm xã hội.",statementEn:"Assessing integration requires economic indicators together with distribution of benefits, costs, and social experience.",sourceId:"source-g12-gso-development",locator:"GSO data portal — year-defined statistics and metadata",note:"Claim là khung đánh giá, không nêu một con số."}]},
];

for(const lesson of grade12Lessons){lesson.vi.body+=suffixVi;lesson.en.body+=suffixEn;lesson.vi.analysis+=reviewVi;lesson.en.analysis+=reviewEn;}
